package com.hms.services;
import jakarta.persistence.*; import java.io.Serializable; import java.util.UUID;
@Entity @Table(name="doctor_services") public class DoctorServiceLink { @EmbeddedId private Key key; protected DoctorServiceLink(){} public DoctorServiceLink(UUID doctorId,UUID serviceId){key=new Key(doctorId,serviceId);} public Key getKey(){return key;} @Embeddable public static class Key implements Serializable { @Column(name="doctor_id") private UUID doctorId; @Column(name="service_id") private UUID serviceId; protected Key(){} public Key(UUID d,UUID s){doctorId=d;serviceId=s;} public UUID getDoctorId(){return doctorId;} public UUID getServiceId(){return serviceId;} public boolean equals(Object o){return o instanceof Key k&&doctorId.equals(k.doctorId)&&serviceId.equals(k.serviceId);} public int hashCode(){return 31*doctorId.hashCode()+serviceId.hashCode();} } }
